$csrf=(string)($_SESSION['ttb_csrf']??'');if($csrf==='')$_SESSION['ttb_csrf']=$csrf=bin2hex(random_bytes(24));$manualPool=[];$activityRules=[];foreach(ttb_apply_lesson_rules(ttb_activities($assignments,(array)$data['groups']),$data)as$rule)$activityRules[(string)$rule['id']]=$rule;if($plan&&$mode==='class'&&$class!=='')foreach((array)($plan['unplaced']??[])as$item)if(in_array($class,(array)($item['classes']??[]),true)){$poolKey=(string)($item['subject']??'').'|'.(string)($item['teacher']??'');if(!isset($manualPool[$poolKey])){$item['activity_id']=(string)($item['id']??$item['activity_id']??'');$manualPool[$poolKey]=array_merge($item,(array)($activityRules[$item['activity_id']]??[]));}}
