function tke_warning(array$e):string{global$entries,$data;$reasons=[];if(!empty($e['locked']))$reasons[]='Tiết đã khóa thủ công';if(!empty($e['fixed_day']))$reasons[]='Tiết cố định, chỉ đổi tại mục Ràng buộc';if(!empty($e['pair_id']))$reasons[]='Thuộc cặp hai tiết liền nhau';$limits=ttb_subject_limits($data,(string)$e['subject']);foreach((array)$e['classes']as$class){$daily=0;$session=0;foreach($entries as$x)if(($x['subject']??'')===$e['subject']&&in_array($class,(array)($x['classes']??[]),true)&&(int)$x['day']===(int)$e['day']){$daily++;if($x['session']===$e['session'])$session++;}if($daily>=$limits['daily'])$reasons[]='Đã chạm giới hạn '.$limits['daily'].' tiết môn/lớp/ngày';if($session>=$limits['session'])$reasons[]='Đã chạm giới hạn '.$limits['session'].' tiết môn/lớp/buổi';break;}return implode(' · ',array_values(array_unique($reasons)));}
function tke_matrix(array$entries,array$settings,string$title,bool$compact=false,string$scopeClass='',string$extraClass=''):void{global$data,$manualMode,$manualOpenSessions;$grid=[];$special=[];foreach($entries as$e)$grid[$e['session']][$e['period']][$e['day']][]=$e;foreach((array)($data['special_slots']??[])as$r){$scope=(string)($r['scope']??'school');$value=(string)($r['value']??'');$applies=$scope==='school'||($scopeClass!==''&&(($scope==='class'&&$value===$scopeClass)||($scope==='grade'&&ttb_class_grade($scopeClass)===(ltrim($value,'0')?:'0'))));if($applies)$special[$r['session']][$r['period']][$r['day']][]=$r;}echo'<section class="schedule-card'.($compact?' compact':'').($extraClass!==''?' '.e($extraClass):'').'"><h3 class="matrix-title">'.e($title).'</h3><div class="matrix-scroll"><table class="schedule-grid"><thead><tr><th class="period-head">Tiết</th>';foreach((array)$settings['days']as$d)echo'<th>'.($d===8?'Chủ nhật':'Thứ '.e($d)).'</th>';echo'</tr></thead><tbody>';foreach(['Sáng'=>(int)$settings['morning_periods'],'Chiều'=>(int)$settings['afternoon_periods']]as$session=>$max){for($p=1;$p<=$max;$p++){echo'<tr'.($p===1?' class="session-start"':'').' data-session="'.e($session).'"><th><span>'.$p.'</span><small>'.e($session).'</small></th>';foreach((array)$settings['days']as$d){$cell=(array)($grid[$session][$p][$d]??[]);$notes=(array)($special[$session][$p][$d]??[]);$closed=$manualMode&&!isset($manualOpenSessions[(int)$d.'|'.$session]);echo'<td data-day="'.e($d).'" class="'.($closed?'manual-closed ':($cell||$notes?'has-lesson ':'empty-slot ')).'">';if($closed)echo'<span class="closed-label"><i class="bi bi-dash-circle"></i> Không học</span>';foreach($notes as$r)echo'<div class="special-lesson"><i class="bi bi-calendar-x"></i> '.e($r['label']).'</div>';foreach($cell as$e){$warning=tke_warning($e);$payload=e(json_encode(['id'=>$e['activity_id'],'day'=>$e['day'],'session'=>$e['session'],'period'=>$e['period'],'subject'=>$e['subject'],'classes'=>array_values((array)$e['classes']),'teacher'=>$e['teacher'],'locked'=>!empty($e['locked']),'fixed_day'=>(int)($e['fixed_day']??0),'fixed_session'=>(string)($e['fixed_session']??''),'fixed_period'=>(int)($e['fixed_period']??0),'pair_id'=>(string)($e['pair_id']??''),'warning'=>$warning],JSON_UNESCAPED_UNICODE));echo'<button type="button" class="lesson'.(!empty($e['locked'])?' locked':'').(!empty($e['fixed_day'])?' fixed':'').(!empty($e['pair_id'])?' paired':'').'" title="'.e($warning).'" data-entry="'.$payload.'"><strong>'.e($e['subject']).'</strong><small>'.e(implode(' + ',$e['classes'])).' · '.e($e['teacher']).'</small>'.((!empty($e['locked'])||!empty($e['fixed_day']))?'<span class="lock-badge"><i class="bi bi-lock-fill"></i> Khóa</span>':'').'</button>';}echo'</td>';}echo'</tr>';}}echo'</tbody></table></div></section>';}
