blocked.forEach(function(b){teacherBlocked.add(b.teacher+'|'+slotKey(b))});classBlocked.forEach(function(b){classBlockedSet.add(b.class+'|'+slotKey(b))});scopeBlocks.forEach(function(b){var key=slotKey(b);if(b.scope==='school')schoolBlocked.add(key);else if(b.scope==='grade')gradeBlocked.add(String(b.value)+'|'+key);else if(b.scope==='class')scopeClassBlocked.add(String(b.value)+'|'+key)});
function overlaps(a,b){return a.teacher===b.teacher||(a.classes||[]).some(function(c){return(b.classes||[]).includes(c)})}
function isBlocked(e,s){var key=slotKey(s);if(schoolBlocked.has(key)||teacherBlocked.has(e.teacher+'|'+key))return true;return(e.classes||[]).some(function(c){var match=String(c).match(/\d+/),grade=match?String(Number(match[0])):'';return classBlockedSet.has(c+'|'+key)||scopeClassBlocked.has(c+'|'+key)||(grade&&gradeBlocked.has(grade+'|'+key))})}
function limitsFor(subject){var x=limitExceptions[subject]||{},daily=Math.max(1,Number(x.daily||limitSettings.daily||2)),session=Math.max(1,Number(x.session||limitSettings.session||1));return{daily:daily,session:Math.min(daily,session)}}
function constraintReason(e,s,ignore){if(manualMode&&!manualOpenSessions.has(String(s.day)+'|'+s.session))return'Buổi này được đánh dấu không học';if(isBlocked(e,s))return'Giáo viên/lớp bận hoặc ô không học';if(e.fixed_day&&(Number(s.day)!==Number(e.fixed_day)||s.session!==e.fixed_session||Number(s.period)!==Number(e.fixed_period)))return'Tiết đã được xếp cố định';if(e.pair_id){var partner=allEntries.find(function(x){return x.pair_id===e.pair_id&&x.activity_id!==e.activity_id});if(partner&&(Number(s.day)!==Number(partner.day)||s.session!==partner.session||Math.abs(Number(s.period)-Number(partner.period))!==1))return'Phải giữ liền với tiết còn lại trong cặp'}var ignored=new Set(ignore||[]),limits=limitsFor(e.subject);for(var i=0;i<(e.classes||[]).length;i++){var c=e.classes[i],daily=0,session=0;allEntries.forEach(function(x){if(ignored.has(x.activity_id)||x.subject!==e.subject||!(x.classes||[]).includes(c)||Number(x.day)!==Number(s.day))return;daily++;if(x.session===s.session)session++});if(daily>=limits.daily)return'Đã đủ '+limits.daily+' tiết môn/lớp/ngày';if(session>=limits.session)return'Đã đủ '+limits.session+' tiết môn/lớp/buổi'}return''}
function cellSlot(cell){var row=cell.parentElement;return{day:Number(cell.dataset.day||days[cell.cellIndex-1]),session:row.dataset.session,period:Number(row.querySelector('th span').textContent)}}
function conflicts(e,s,ignore){var ignored=new Set(ignore);return(slotIndex.get(slotKey(s))||[]).filter(function(x){return!ignored.has(x.activity_id)&&overlaps(e,x)})}
function clearTargets(){document.querySelectorAll('.schedule-grid td').forEach(function(c){c.classList.remove('move-ok','swap-ok','move-no');delete c.dataset.action;delete c.dataset.targetId;delete c.title});document.querySelectorAll('.lesson.selected').forEach(function(x){x.classList.remove('selected')})}
function editableCells(){return document.querySelectorAll(<?=json_encode($mode==='class'?'.class-editor-card .schedule-grid td':'.schedule-grid td')?>)}
function markTargets(e,button,source){clearTargets();selected=e;selectedSource=source||'placed';button.classList.add('selected');
editableCells().forEach(function(cell){var target=cellSlot(cell),ignore=selectedSource==='placed'?[e.activity_id]:[],hits=conflicts(e,target,ignore),reason=constraintReason(e,target,ignore.concat(hits.map(function(x){return x.activity_id})));if(reason){cell.classList.add('move-no');cell.title=reason;return}if(hits.length===0){cell.classList.add('move-ok');cell.dataset.action=selectedSource==='unplaced'?'entry_add':'move';return}if(selectedSource==='placed'&&hits.length===1){var other=hits[0],sourceSlot={day:e.day,session:e.session,period:Number(e.period)},otherBlocked=constraintReason(other,sourceSlot,[e.activity_id,other.activity_id]),otherHits=conflicts(other,sourceSlot,[e.activity_id,other.activity_id]),moveHits=conflicts(e,target,[e.activity_id,other.activity_id]);if(!otherBlocked&&!otherHits.length&&!moveHits.length&&!constraintReason(e,target,[e.activity_id,other.activity_id])){cell.classList.add('swap-ok');cell.dataset.action='swap';cell.dataset.targetId=other.activity_id;return}}cell.classList.add('move-no')})}
function postMove(cell){if(!selected||!cell.dataset.action)return;var slot=cellSlot(cell),form=document.createElement('form');form.method='post';form.action='/tkb_xep.php';var fields={csrf:'<?=e($csrf)?>',action:cell.dataset.action,return_tab:'plan',plan_id:'<?=e($plan['id']??'')?>',activity_id:selected.activity_id,day:slot.day,session:slot.session,period:slot.period,target_id:cell.dataset.targetId||'',return_mode:'<?=e($mode)?>',return_class:'<?=e($class)?>',return_teacher:selected.teacher||'<?=e($teacher)?>'};Object.keys(fields).forEach(function(name){var input=document.createElement('input');input.type='hidden';input.name=name;input.value=fields[name];form.appendChild(input)});document.body.appendChild(form);form.submit()}
function quickGrade(className){var m=String(className||'').match(/\d+/);return m?String(Number(m[0])):''}
function quickScopeClasses(){var scope=document.getElementById('quickScope').value,target=document.getElementById('quickTarget').value;if(scope==='school')return quickClasses.slice();if(scope==='class')return target?[target]:[];return quickClasses.filter(function(c){return quickGrade(c)===String(Number(target))})}
function rebuildQuickTarget(){var scope=document.getElementById('quickScope').value,target=document.getElementById('quickTarget'),current=target.value,items=scope==='grade'?quickGrades:(scope==='class'?quickClasses:[]);target.innerHTML='';if(scope==='school'){var option=document.createElement('option');option.value='';option.textContent='Toàn trường';target.appendChild(option);target.disabled=true}else{target.disabled=false;items.forEach(function(value){var option=document.createElement('option');option.value=value;option.textContent=scope==='grade'?'Khối '+value:value;target.appendChild(option)});if(items.includes(current))target.value=current;else if(scope==='class'&&items.includes(<?=json_encode($class,JSON_UNESCAPED_UNICODE)?>))target.value=<?=json_encode($class,JSON_UNESCAPED_UNICODE)?>}renderQuickSubjects()}
function quickEligible(){var scope=document.getElementById('quickScope').value,target=document.getElementById('quickTarget').value;return quickUnplaced.filter(function(item){var itemClasses=item.classes||[];if(scope==='school')return true;if(scope==='class')return itemClasses.includes(target);return itemClasses.some(function(c){return quickGrade(c)===String(Number(target))})})}
function quickFreeCapacity(classes,selectedSlots){var free=0,settings={Sáng:<?=json_encode((int)$data['settings']['morning_periods'])?>,Chiều:<?=json_encode((int)$data['settings']['afternoon_periods'])?>};classes.forEach(function(className){selectedSlots.forEach(function(slotChoice){var parts=String(slotChoice).split('|'),day=Number(parts[0]),session=parts[1];if(!settings[session]||manualMode&&manualOpenSessions.size&&!manualOpenSessions.has(String(day)+'|'+session))return;for(var period=1;period<=settings[session];period++){var key=String(day)+'|'+session+'|'+String(period),grade=quickGrade(className);if(schoolBlocked.has(key)||classBlockedSet.has(className+'|'+key)||scopeClassBlocked.has(className+'|'+key)||(grade&&gradeBlocked.has(grade+'|'+key)))continue;var occupied=allEntries.some(function(e){return Number(e.day)===day&&e.session===session&&Number(e.period)===period&&(e.classes||[]).includes(className)});if(!occupied)free++}})});return free}
function renderQuickSubjects(){var body=document.getElementById('quickSubjects');if(!body)return;var eligible=quickEligible(),groups={};eligible.forEach(function(item){var subject=String(item.subject||'');groups[subject]=(groups[subject]||0)+1});body.innerHTML='';Object.keys(groups).sort(function(a,b){return a.localeCompare(b,'vi')}).forEach(function(subject){var row=document.createElement('tr');row.innerHTML='<td><strong></strong></td><td><span class="badge text-bg-light border"></span></td><td><input class="form-control form-control-sm quick-period" type="number" min="0" value="0"></td>';row.querySelector('strong').textContent=subject;row.querySelector('.badge').textContent=groups[subject]+' tiết';var input=row.querySelector('input');input.max=groups[subject];input.dataset.subject=subject;input.addEventListener('input',updateQuickStatus);body.appendChild(row)});if(!Object.keys(groups).length)body.innerHTML='<tr><td colspan="3" class="text-muted text-center">Phạm vi này không còn tiết chưa sắp.</td></tr>';updateQuickStatus()}
function updateQuickStatus(){var slotsSelected=Array.from(document.querySelectorAll('.quick-slot:checked')).map(function(x){return x.value}),eligible=quickEligible(),capacity=quickFreeCapacity(quickScopeClasses(),slotsSelected),needed=Math.min(capacity,eligible.length),selection={},total=0;document.querySelectorAll('.quick-period').forEach(function(input){var value=Math.max(0,Math.min(Number(input.max||0),Number(input.value||0)));selection[input.dataset.subject]=value;total+=value});document.getElementById('quickSelection').value=JSON.stringify(selection);var need=document.getElementById('quickNeed'),warning=document.getElementById('quickWarning'),submit=document.getElementById('quickSubmit');if(!slotsSelected.length){need.textContent='Hãy chọn ít nhất một ngày và buổi.';warning.classList.add('d-none');submit.disabled=true;return}need.innerHTML='Các ngày đã chọn còn sức chứa <strong>'+capacity+'</strong> lượt tiết; kho phù hợp có <strong>'+eligible.length+'</strong> tiết. Cần chọn <strong>'+needed+'</strong> tiết.';var diff=total-needed;if(diff===0&&needed>0){warning.className='alert alert-success mt-2 mb-0';warning.textContent='Đã chọn đủ '+total+' tiết. Có thể xếp nhanh.';submit.disabled=false}else{warning.className='alert alert-warning mt-2 mb-0';warning.textContent=diff<0?'Đang chọn thiếu '+Math.abs(diff)+' tiết.':'Đang chọn thừa '+diff+' tiết.';submit.disabled=true}}
function openManualAdd(cell){if(<?=json_encode($mode)?>!=='class')return;var slot=cellSlot(cell),label=(Number(slot.day)===8?'Chủ nhật':'Thứ '+slot.day)+' · '+slot.session+' · Tiết '+slot.period,select=document.getElementById('manualActivity'),valid=0,reasons=[];document.getElementById('manualDay').value=slot.day;document.getElementById('manualSession').value=slot.session;document.getElementById('manualPeriod').value=slot.period;document.getElementById('manualSlotLabel').textContent=label;Array.from(select.options).forEach(function(option){var item=manualPoolData.find(function(x){return String(x.activity_id)===String(option.value)}),reason='';if(item){var hits=conflicts(item,slot,[]);reason=hits.length?'Giáo viên hoặc lớp đã có tiết tại ô này':constraintReason(item,slot,[])}else reason='Không tìm thấy tiết trong kho';option.dataset.base=option.dataset.base||option.textContent;option.dataset.invalid=reason?'1':'';option.disabled=!!reason;option.textContent=option.dataset.base+(reason?' — Không thể: '+reason:'');if(reason)reasons.push(reason);else valid++});var warning=document.getElementById('manualWarning');warning.textContent=valid?'Chỉ các dòng không bị khóa mới có thể thêm.':'Không có tiết nào thêm được vào ô này: '+Array.from(new Set(reasons)).join('; ');warning.classList.toggle('d-none',valid>0);document.getElementById('manualSubmit').disabled=valid<1;var search=document.getElementById('manualSearch');search.value='';filterManualPool('');bootstrap.Modal.getOrCreateInstance(document.getElementById('manualAddModal')).show()}
function filterManualPool(query){query=String(query||'').trim().toLocaleLowerCase('vi');var select=document.getElementById('manualActivity'),first=null;Array.from(select.options).forEach(function(option){var show=!query||String(option.dataset.search||'').includes(query);option.hidden=!show;option.disabled=!show||option.dataset.invalid==='1';if(show&&!option.disabled&&!first)first=option});select.value=first?first.value:'';document.getElementById('manualSubmit').disabled=!first}
function renderTeacherPreview(name){var card=document.querySelector('.teacher-preview-card');if(!card||!name)return;card.querySelector('.matrix-title').textContent='TKB giáo viên '+name;card.querySelectorAll('.lesson').forEach(function(x){x.remove()});allEntries.filter(function(e){return e.teacher===name}).forEach(function(e){var row=Array.from(card.querySelectorAll('tr[data-session]')).find(function(r){return r.dataset.session===e.session&&Number(r.querySelector('th span').textContent)===Number(e.period)}),cell=row?row.querySelector('td[data-day="'+Number(e.day)+'"]'):null;if(!cell)return;var button=document.createElement('button');button.type='button';button.className='lesson';var strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=e.subject;small.textContent=(e.classes||[]).join(' + ');button.append(strong,small);cell.appendChild(button);cell.classList.remove('empty-slot');cell.classList.add('has-lesson')});card.querySelectorAll('td').forEach(function(cell){if(!cell.querySelector('.lesson')&&!cell.classList.contains('manual-closed')){cell.classList.remove('has-lesson');cell.classList.add('empty-slot')}});var select=document.getElementById('teacherPreviewSelect');if(select&&Array.from(select.options).some(function(o){return o.value===name}))select.value=name}
function filterUnplaced(){var query=String(document.getElementById('unplacedSearch')?.value||'').trim().toLocaleLowerCase('vi'),subject=document.getElementById('unplacedSubject')?.value||'',teacher=document.getElementById('unplacedTeacher')?.value||'',count=0;document.querySelectorAll('#unplacedList .unplaced-item').forEach(function(item){var show=(!query||String(item.dataset.search||'').includes(query))&&(!subject||item.dataset.subject===subject)&&(!teacher||item.dataset.teacher===teacher);item.hidden=!show;if(show)count++});var out=document.getElementById('unplacedVisibleCount');if(out)out.textContent=count}
function openEditor(e){document.getElementById('entryTitle').textContent=e.subject+' · '+(e.classes||[]).join(' + ');document.getElementById('entryMeta').textContent=e.teacher;var warning=document.getElementById('entryWarning');warning.textContent=e.warning||'';warning.classList.toggle('d-none',!e.warning);document.getElementById('entryId').value=e.activity_id;document.getElementById('lockEntryId').value=e.activity_id;document.getElementById('deleteEntryId').value=e.activity_id;document.getElementById('swapSourceId').value=e.activity_id;var swapSelect=document.getElementById('swapTargetId');swapSelect.innerHTML='<option value="">Chọn tiết cùng lớp cần đổi…</option>';var selectedClasses=new Set(e.classes||[]);allEntries.filter(function(x){return x.activity_id!==e.activity_id&&(x.classes||[]).some(function(className){return selectedClasses.has(className)})}).sort(function(a,b){return Number(a.day)-Number(b.day)||String(a.session).localeCompare(String(b.session))||Number(a.period)-Number(b.period)}).forEach(function(x){var option=document.createElement('option');option.value=x.activity_id;option.textContent=(x.day===8?'CN':'T'+x.day)+' · '+x.session+' '+x.period+' — '+x.subject+' · '+(x.classes||[]).join(' + ')+' · '+x.teacher;swapSelect.appendChild(option)});document.getElementById('entryDay').value=e.day;document.getElementById('entrySession').value=e.session;document.getElementById('entryPeriod').value=e.period;document.querySelectorAll('#moveForm select,#moveForm input[type="number"],#moveForm button').forEach(function(control){control.disabled=!!e.fixed_day});document.getElementById('lockButton').textContent=e.locked?'Mở khóa tiết':'Khóa tiết';bootstrap.Modal.getOrCreateInstance(document.getElementById('entryModal')).show()}
